const input = $input.first().json;
const OFFSET = 7 * 3600 * 1000;
const localYmd = (ms) => new Date(ms + OFFSET).toISOString().slice(0, 10);
const isDate = (s) => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s);
const addDays = (ymd, n) => new Date(new Date(ymd + 'T00:00:00Z').getTime() + n * 86400000).toISOString().slice(0, 10);

const today = localYmd(Date.now());
const start = isDate(input.date_range_start) ? input.date_range_start : today;
let end = isDate(input.date_range_end) ? input.date_range_end : addDays(start, 6);
if (end < start) end = start;
const maxEnd = addDays(start, 13); // gioi han 14 ngay
if (end > maxEnd) end = maxEnd;

const PERIOD = ['morning', 'afternoon', 'evening', 'any'];
return [{ json: {
  user_id: input.user_id,
  duration_minutes: Math.min(480, Math.max(15, Number.parseInt(input.duration_minutes, 10) || 60)),
  preferred_period: PERIOD.includes(input.preferred_period) ? input.preferred_period : 'any',
  date_range_start: start,
  date_range_end: end,
  time_min: start + 'T00:00:00+07:00',
  time_max: end + 'T23:59:59+07:00'
} }];

const cfg = $('Prepare Time Range').first().json;
const events = $input.all().map((i) => i.json).filter((e) => e && Object.keys(e).length > 0);

const OFFSET = 7 * 3600 * 1000; // Asia/Ho_Chi_Minh = UTC+7, khong co DST
const HOUR = 3600 * 1000, STEP = 30 * 60 * 1000, DAY = 86400000;
const toLocal = (ms) => new Date(ms + OFFSET).toISOString().slice(0, 19).replace('T', ' ');
const toIso = (ms) => new Date(ms + OFFSET).toISOString().slice(0, 19) + '+07:00';
const parseTime = (v) => {
  if (!v) return null;
  const raw = typeof v === 'string' ? v : (v.dateTime || v.date);
  if (!raw) return null;
  const ms = new Date(raw.includes('T') ? raw : raw + 'T00:00:00+07:00').getTime();
  return Number.isNaN(ms) ? null : ms;
};

// 1) Khoang ban (bo qua su kien da huy / transparent)
const busy = [];
for (const ev of events) {
  if (ev.status === 'cancelled' || ev.transparency === 'transparent') continue;
  const s = parseTime(ev.start);
  let e = parseTime(ev.end);
  if (s !== null && e === null) e = s + DAY;
  if (s !== null && e !== null && e > s) busy.push({ start: s, end: e, summary: ev.summary || '(khong tieu de)' });
}

// 2) Sinh khung trong
const WINDOWS = { morning: [6, 12], afternoon: [12, 18], evening: [18, 22], any: [6, 22] };
const [h0, h1] = WINDOWS[cfg.preferred_period] || WINDOWS.any;
const dur = cfg.duration_minutes * 60 * 1000;
const firstDay = new Date(cfg.date_range_start + 'T00:00:00+07:00').getTime();
const lastDay = new Date(cfg.date_range_end + 'T00:00:00+07:00').getTime();
const days = Math.round((lastDay - firstDay) / DAY) + 1;
const notBefore = Date.now() + 15 * 60 * 1000;

const free = [];
for (let d = 0; d < days && free.length < 200; d++) {
  const dayStart = firstDay + d * DAY;
  const winEnd = dayStart + h1 * HOUR;
  for (let t = dayStart + h0 * HOUR; t + dur <= winEnd && free.length < 200; t += STEP) {
    if (t < notBefore) continue;
    if (busy.some((b) => t < b.end && t + dur > b.start)) continue;
    free.push({
      start_time: toLocal(t), end_time: toLocal(t + dur),
      date: toLocal(t).slice(0, 10), period: cfg.preferred_period,
      start_iso: toIso(t), end_iso: toIso(t + dur)
    });
  }
}

return [{ json: {
  user_id: cfg.user_id,
  duration_minutes: cfg.duration_minutes,
  preferred_period: cfg.preferred_period,
  date_range_start: cfg.date_range_start,
  date_range_end: cfg.date_range_end,
  busy_count: busy.length,
  busy_events: busy.map((b) => ({ summary: b.summary, start_time: toLocal(b.start), end_time: toLocal(b.end) })),
  free_count: free.length,
  free_slots: free
} }];
